def main():
    os.makedirs(BRAND_DIR, exist_ok=True)

    files = {
        "qalisuite-new-icon.svg": create_cropped_icon(),
        "qalisuite-new-favicon.svg": create_favicon(),
        "qalisuite-new-logo-dark.svg": create_horizontal_logo_dark(),
        "qalisuite-new-logo-light.svg": create_horizontal_logo_light(),
    }

    for name, content in files.items():
        path = BRAND_DIR / name
        # Clean up whitespace
        lines = [line.rstrip() for line in content.strip().split('\n')]
        clean = '\n'.join(lines) + '\n'
        path.write_text(clean)
        size = len(clean)
        print(f"  {name}: {size:,} bytes")

    # Also report original sizes for comparison
    print("\nOriginal sizes:")
    for name in ["qalisuite-logo-icon.svg", "qalisuite1.svg", "qalisuite2.svg"]:
        path = BRAND_DIR / name
        if path.exists():
            print(f"  {name}: {path.stat().st_size:,} bytes")

    print("\nDone! New optimized files created in public/brand/")


if __name__ == "__main__":
    main()
